# Original NumPy native ordering replaces the former cross-batch tie rejection.
MODULES=[(name,status,rust+(['rust/rapiddoc-inference/src/ocr/numpy_argsort.rs','rust/rapiddoc-inference/src/numpy_argsort.cpp',
 'rust/rapiddoc-inference/build.rs','rust/rapiddoc-inference/vendor/x86-simd-sort/SOURCE.json',
 'licenses/MIGRATION-NOTICES.txt']if name=='recognition_batch'else[]),python,suites,
 ('12组原CPU批识别（包括原标记unsupported的同宽高比跨批）使用同一NumPy 2.4.6原生x86排序后端；AVX2/AVX512运行时分派，非SIMD使用原NumPy introsort；228组排序/padding参考及reported 03整篇状态见2026-10-28-reported-speed-and-ocr.md。无通用CPU/版本一致性或性能优势声明。'if name=='recognition_batch'else scope))
 for name,status,rust,python,suites,scope in MODULES]

def build():
    from license_bundle import read_notice
    sdk=ROOT/'bindings/python/python/rapid_doc_rust/__init__.py'
    tree=ast.parse(sdk.read_text(encoding='utf-8'));defaults={}
    for node in tree.body:
        if isinstance(node,ast.FunctionDef)and node.name in ('organize_page_text','recognize_pdf_page_hybrid'):
            defaults[node.name]={a.arg:ast.literal_eval(v)for a,v in zip(node.args.kwonlyargs,node.args.kw_defaults)if v is not None and a.arg in ('experimental','prefer_native_tables','line_order','block_order')}
    assert defaults['organize_page_text']==dict(experimental=False,line_order='source',block_order='source')
    assert defaults['recognize_pdf_page_hybrid']==dict(experimental=False,prefer_native_tables=False)
    modules=[]
    for name,status,rust,python,suites,limits in MODULES:
        rust=list(dict.fromkeys('bindings/python/python/rapid_doc_rust/licenses/THIRD_PARTY_NOTICES.txt'
             if p=='bindings/python/python/rapid_doc_rust/licenses/MIGRATION-NOTICES.txt' else p for p in rust))
        if 'rust/rapiddoc/src/processing/table/table_native_text.rs' in rust:
            rust=list(dict.fromkeys(rust+['rust/rapiddoc/src/processing/table/table_native_text/rotation.rs']))
        if 'rust/rapiddoc/src/processing/table/table_native_engine.rs' in rust:
            rust=list(dict.fromkeys(rust+['rust/rapiddoc/src/processing/table/table_native_hierarchical.rs','rust/rapiddoc/src/processing/table/table_native_text_quality.rs']))
            python=list(dict.fromkeys(python+['rapid_doc/_vendor/docvortex_core/analyzers/native/pdf/_table_recovery/hierarchical.py','rapid_doc/_vendor/docvortex_core/analyzers/native/pdf/_table_recovery/text_quality.py']))
        if 'rust/rapiddoc/src/processing/document/inline_output/mod.rs' in rust:
            rust=list(dict.fromkeys(rust+['rust/rapiddoc/src/processing/document/inline_output/conflicts.rs']))
        # Registration remains in lib.rs; the implementation is now in adapters.
        if 'bindings/python/src/lib.rs' in rust:
            rust = list(dict.fromkeys(rust + [
                f'bindings/python/src/{domain}.rs'
                for domain in ('assets','diagnostics','formula','models','ocr','pdf','tables')
            ]))
        for suite in suites:
            if suite!='pdf_render':assert (ROOT/f'bindings/python/tests/{suite}_install.py').is_file()
        modules.append(dict(id=name,status=status,rust_sources={p:digest(read_notice(ROOT/p))for p in rust},
            python_references={p:digest((ROOT/p).read_bytes())for p in python},installed_suites=suites,
            evidence='authored_contracts_and_independent_component_facts'if status=='experimental_new_rules'else 'see_scope',scope=limits))
    return dict(schema=1,source_commit=subprocess.check_output(['git','rev-parse','HEAD'],cwd=ROOT,text=True).strip(),
        claims=dict(document_python_parity=False,quality_improvement=False,speed_improvement=False,memory_improvement=False),
        defaults=defaults,modules=modules,
        promotion_rule='人工审查旧 Python 整文档差分及相同条件耗时/峰值内存后才能提升默认策略；作者合同不能替代旧基线')


def main():
    parser=argparse.ArgumentParser(description=__doc__);parser.add_argument('--check',action='store_true');args=parser.parse_args()
    result=build();paths=[ROOT/'packaging/compatibility-audit.json']
    if args.check:
        for p in paths:assert json.loads(p.read_text(encoding='utf-8'))==result,f'Stale compatibility audit: {p}'
    else:
        for p in paths:write_json(p,result)
    print(f'Compatibility audit: {len(result["modules"])} modules; experimental defaults disabled; no document parity/performance claims')


if __name__=='__main__':main()
